    println!("  ✓ Total coefficients match (degree+1)² formula: {}", expected_total);

    // Verify coefficient count for each degree
    // Degree d has (d+1)² total coefficients from degree 0 to d
    let test_cases = vec![
        (0, 1),   // Degree 0: (0+1)² = 1
