    ];

    for (degree, start_idx, end_idx) in layout {
        let count = end_idx - start_idx + 1;
        let expected_count_for_degree = 2 * degree + 1; // Number of coefficients for degree d (not cumulative)

        println!("  Degree {}: indices {}-{} ({} coefficients)",
